sys_script.script:
/**
 * ESR - Auto assign support group   (before / insert + update / order 200)
 *
 * Routes a ticket to the support group that owns its category, re-routes it
 * while nobody has personally picked it up, and records when a named agent
 * takes ownership.
 *
 *   assignment_group empty + category set      -> derive group from category
 *   category changed, no assignee, state 1|2   -> re-route to the new group
 *   assigned_to newly set while state 1 (New)  -> state 2 (Assigned)
 *
 * DELIBERATELY NOT DONE HERE:
 *
 *   - Group routing does NOT advance the state. A ticket that has merely been
 *     routed to a queue is still New: no human has looked at it yet. This rule
 *     previously bumped New -> Assigned as soon as a group was derived, which
 *     happens during the insert itself, so a brand new ticket could never be
 *     observed in the New state.
 *
 *   - Nothing here sets In Progress. Moving to In Progress means an agent has
 *     explicitly started work, which is what the "Accept" UI action is for.
 *     Deriving it automatically would report work as started before anybody
 *     had touched the ticket.
 *
 * This is a before rule, so field writes persist with the save in flight -
 * current.update() is deliberately never called.
 */
;(function autoAssignSupportGroup(current, previous) {
    var utils = new x_412993_employe_1.EsrTicketUtils()

    var isInsert = current.operation() === 'insert'
    var category = current.getValue('category')
    var assignedTo = current.getValue('assigned_to')
    var group = current.getValue('assignment_group')

    /* ---------------------------------------------------------------
     * 1. Unassigned group -> derive it from the category
     * ------------------------------------------------------------- */
    if (!group && category) {
        var derivedGroup = utils.getGroupForCategory(category)
        if (derivedGroup) {
            current.setValue('assignment_group', derivedGroup)
            group = derivedGroup
        }
    }

    /* ---------------------------------------------------------------
     * 2. Category re-categorised on an existing ticket that nobody has
     *    personally picked up yet, and which is still New / Assigned
     *    -> re-route to the new category's group
     * ------------------------------------------------------------- */
    if (!isInsert && category && !assignedTo && current.category.changes()) {
        var stateNow = current.getValue('state')
        if (stateNow === '1' || stateNow === '2') {
            var rerouted = utils.getGroupForCategory(category)
            if (rerouted && rerouted !== group) {
                current.setValue('assignment_group', rerouted)
                group = rerouted
            }
        }
    }

    /* ---------------------------------------------------------------
     * 3. A named agent now owns the ticket -> New becomes Assigned
     *
     *    Only promotes out of New. A ticket already In Progress, On Hold,
     *    Resolved or Closed is left alone, so a reassignment never drags
     *    the lifecycle backwards.
     * ------------------------------------------------------------- */
    var newlyAssigned = !!assignedTo && (isInsert || current.assigned_to.changes())
    if (newlyAssigned && current.getValue('state') === '1') {
        current.setValue('state', '2')
    }
})(current, previous)
